krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                              pkinit_plg_crypto_context plg_cryptoctx,
                                              pkinit_req_crypto_context req_cryptoctx,
                                              pkinit_identity_crypto_context id_cryptoctx,
                                              unsigned char *pdid_buf,
                                              unsigned int pkid_len,
                                              int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data = {0};
    pkinit_kdc_identity_crypto_context kdc_idctx = NULL;
    krb5_principal kdc_princ = NULL;
    krb5_principal issuer = NULL;
    krb5_kdcfree kdcfree = NULL;
    krb5_kdcenc kdcenc = NULL;
    pkinit_req_pk_preq preq = NULL;
    pkinit_req_pk_preq_body preq_body = NULL;
    pkinit_identity_crypto_context_identity cert_identity = NULL;
    krb5_cert_get_issuer_fn get_issuer_fn = NULL;
    krb5_cert_get_serial_fn get_serial_fn = NULL;
    krb5_data cert_issuer = {0};
    krb5_data pdid_issuer = {0};
    krb5_data cert_serial = {0};
    krb5_data pdid_serial = {0};

    pdid_data.data = pdid_buf;
    pdid_data.length = pkid_len;

    kret = pkinit_decode_PKID(&pdid_data, &preq);
    if (kret)
        goto cleanup;

    kret = pkinit_get_kdc_identity(context, plg_cryptoctx, id_cryptoctx, &kdc_idctx);
    if (kret)
        goto cleanup;

    kret = kdc_idctx->crypto->get_principal(context, kdc_idctx, &kdc_princ);
    if (kret)
        goto cleanup;

    kret = krb5_unparse_name(context, kdc_princ, &issuer);
    if (kret)
        goto cleanup;

    kret = kdc_idctx->crypto->get_cert_issuer(context, kdc_idctx, &cert_issuer);
    if (kret)
        goto cleanup;

    kret = kdc_idctx->crypto->get_cert_serial(context, kdc_idctx, &cert_serial);
    if (kret)
        goto cleanup;

    kret = pkinit_get_preq_body(context, preq, &preq_body);
    if (kret)
        goto cleanup;

    kret = pkinit_get_cert_identity(context, preq_body->padata, &cert_identity);
    if (kret)
        goto cleanup;

    kret = cert_identity->crypto->get_issuer(context, cert_identity, &pdid_issuer);
    if (kret)
        goto cleanup;

    kret = cert_identity->crypto->get_serial(context, cert_identity, &pdid_serial);
    if (kret)
        goto cleanup;

    *valid_kdcPkId = (krb5_data_equal(&cert_issuer, &pdid_issuer) &&
                      krb5_data_equal(&cert_serial, &pdid_serial));

cleanup:
    if (cert_identity)
        cert_identity->crypto->free_identity(context, cert_identity);
    if (preq_body)
        pkinit_free_preq_body(context, preq_body);
    if (preq)
        pkinit_free_PKID(context, preq);
    if (cert_issuer.data)
        krb5_free_data_contents(context, &cert_issuer);
    if (cert_serial.data)
        krb5_free_data_contents(context, &cert_serial);
    if (pdid_issuer.data)
        krb5_free_data_contents(context, &pdid_issuer);
    if (pdid_serial.data)
        krb5_free_data_contents(context, &pdid_serial);
    if (issuer)
        free(issuer);

    return kret;
}

krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                               pkinit_plg_crypto_context plg_cryptoctx,
                                               pkinit_req_crypto_context req_cryptoctx,
                                               pkinit_identity_crypto_context id_cryptoctx,
                                               unsigned char *pdid_buf,
                                               unsigned int pkid_len,
                                               int *valid_kdcPkId) {
    krb5_error_code ret = 0;
    krb5_data pdid_data;
    pkinit_pkeyid pkeyid = NULL;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    ret = decode_pkinit_pkeyid(&pdid_data, &pkeyid);
    if (ret)
        goto cleanup;

    ret = compare_pkeyid_with_kdc_cert(context, pkeyid, req_cryptoctx, id_cryptoctx);
    if (ret)
        goto cleanup;

    *valid_kdcPkId = 1;

cleanup:
    if (pkeyid) {
        free_pkinit_pkeyid(pkeyid);
    }

    return ret;
}

krb5_error_code check_valid_kdcPkId(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx,
                                    pkinit_req_crypto_context req_cryptoctx,
                                    pkinit_identity_crypto_context id_cryptoctx,
                                    unsigned char *pdid_buf, unsigned int pkid_len,
                                    int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    krb5_data pdid_data;
    pkinit_pkeyid pkeyid = NULL;
    krb5_X509_certificate_chain chain = NULL;
    krb5_principal kdc_principal = NULL;
    krb5_get_in_tkt_opt in_tkt_opt;
    krb5_flags flags;
    krb5_keyblock *key = NULL;
    krb5_kdc_free_fn free_fn = NULL;
    void *free_data = NULL;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    if ((retval = pkinit_decode_PKINIT_KDC_PUBLIC_KEY_ID(&pdid_data, &pkeyid)) != 0)
        goto cleanup;

    if ((retval = krb5_kdc_get_kdc_certificate(context, plg_cryptoctx->kdc_realm, &chain, &kdc_principal, &in_tkt_opt, &flags, &key)) != 0)
        goto cleanup;

    if (!chain || chain->length < 1) {
        retval = KRB5KDCERR_BADOID;
        goto cleanup;
    }

    if (pkeyid->serialNumber == NULL || pkeyid->issuer == NULL) {
        retval = KRB5KDCERR_BADOID;
        goto cleanup;
    }

    {
        krb5_X509_certificate cert = chain->val[0];
        krb5_X509_NAME issuer;
        krb5_X509_INTEGER serial;

        if ((retval = krb5_X509_certificate_get_issuer(cert, &issuer)) != 0)
            goto cleanup;

        if ((retval = krb5_X509_certificate_get_serial(cert, &serial)) != 0)
            goto cleanup;

        if (!krb5_X509_NAME_cmp(issuer, pkeyid->issuer) && krb5_X509_INTEGER_cmp(serial, pkeyid->serialNumber) == 0)
            *valid_kdcPkId = 1;
        else
            *valid_kdcPkId = 0;
    }

cleanup:
    if (pkeyid)
        pkinit_free_PKINIT_KDC_PUBLIC_KEY_ID(pkeyid);
    if (chain)
        krb5_X509_certificate_chain_free(context, chain);
    if (kdc_principal)
        krb5_free_principal(context, kdc_principal);
    if (key)
        krb5_free_keyblock(context, key);
    if (free_fn)
        free_fn(free_data);

    return retval;
}

krb5_error_code validate_kdc_public_key_identifier(krb5_context context,
                                                   pkinit_plg_crypto_context plg_cryptoctx,
                                                   pkinit_req_crypto_context req_cryptoctx,
                                                   pkinit_identity_crypto_context id_cryptoctx,
                                                   unsigned char *pdid_buf,
                                                   unsigned int pkid_len,
                                                   int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    pkinit_pvid pvid = NULL;
    krb5_principal kdc_issuer = NULL;
    krb5_data kdc_serial_as_data;
    krb5_int32 kdc_serial;

    *valid_kdcPkId = 0;

    if (!pdid_buf || pkid_len == 0) {
        return KRB5_PREAUTH_BAD_PVNO;
    }

    if ((retval = decode_pkinit_pvid(pdid_buf, pkid_len, &pvid)) != 0) {
        goto cleanup;
    }

    if ((retval = krb5_build_principal_context(context, &kdc_issuer,
                                               pvid->issuer.name.name_string->len,
                                               pvid->issuer.name.name_string->val,
                                               NULL)) != 0) {
        goto cleanup;
    }

    kdc_serial_as_data.data = pvid->serial_number->val;
    kdc_serial_as_data.length = pvid->serial_number->length;

    if ((retval = krb5_data_to_int32(context, &kdc_serial_as_data, &kdc_serial)) != 0) {
        goto cleanup;
    }

    if (id_cryptoctx->kdc_issuer && id_cryptoctx->kdc_serial) {
        if (krb5_principal_compare(context, id_cryptoctx->kdc_issuer, kdc_issuer) &&
            (kdc_serial == id_cryptoctx->kdc_serial)) {
            *valid_kdcPkId = 1;
        }
    }

cleanup:
    if (pvid) {
        free_pkinit_pvid(pvid);
    }
    if (kdc_issuer) {
        krb5_free_principal(context, kdc_issuer);
    }

    return retval;
}

krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                               pkinit_plg_crypto_context plg_cryptoctx,
                                               pkinit_req_crypto_context req_cryptoctx,
                                               pkinit_identity_crypto_context id_cryptoctx,
                                               unsigned char *pdid_buf,
                                               unsigned int pkid_len,
                                               int *valid_kdcPkId) {
    krb5_error_code ret = 0;
    krb5_data pdid_data;
    krb5_principal kdc_principal = NULL;
    krb5_cert_kdc_identifier *kdc_id = NULL;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    ret = pkinit_decode_kdc_identifier(context, plg_cryptoctx, &pdid_data, &kdc_id);
    if (ret) {
        goto cleanup;
    }

    ret = krb5_kdc_cert_compare_identifier(context, kdc_id, &id_cryptoctx->kdc_issuer, id_cryptoctx->kdc_serial, valid_kdcPkId);
    if (ret) {
        goto cleanup;
    }

cleanup:
    if (kdc_id) {
        krb5_free_cert_kdc_identifier(context, kdc_id);
    }
    return ret;
}
